examples.code:
New-OfficePowerPoint -Path .\Reports\Kickoff.pptx {
    PowerPointSlide -Title 'Northwind migration kickoff' -Subtitle 'Scope, timeline and owners'
}

$sales = Import-OfficeExcel -Path .\Reports\Q3-Sales.xlsx -Sheet 'By region'
$priorities = Import-OfficeExcel -Path .\Reports\Q3-Sales.xlsx -Sheet 'Priorities'
New-OfficePowerPoint -Path .\Reports\Q3-Review.pptx -Theme Boardroom -Show {
    PowerPointFooter {
        PowerPointText 'Contoso | Internal | Slide '
        PowerPointSlideNumber
    }
    PowerPointSlide -Title 'Q3 business review' -Subtitle 'Performance, decisions and priorities'
    PowerPointSlide -Title 'Quarter at a glance' {
        PowerPointKpi '$4.2M' 'Revenue' -Change '+12% vs Q2' -Trend Up
        PowerPointKpi '38%' 'Gross margin' -Change '+2 pt' -Trend Up
        PowerPointKpi '1,284' 'New customers' -Change '+9%' -Trend Up
    }
    PowerPointSlide -Title 'Revenue and margin by region' {
        PowerPointChart -InputObject $sales -Category Region -Value Revenue -Type Column -Title 'Revenue (USD k)'
        PowerPointChart -InputObject $sales -Category Region -Value Margin -Type Line -Title 'Margin (%)'
        PowerPointNotes 'Start with EMEA: margin grew faster than revenue.'
    }
    PowerPointSlide -Title 'Next-quarter priorities' {
        PowerPointTable -InputObject $priorities -Property Priority, Owner, Due
    }
}

$teams = Import-OfficeExcel -Path .\Planning\Team-Goals.xlsx
$deck = New-OfficePowerPoint -Theme Minimal
PowerPointSlide -Document $deck -Title 'Team goals' -Subtitle 'FY2026 planning'
foreach ($team in $teams | Group-Object Team) {
    PowerPointSlide -Document $deck -Title $team.Name {
        PowerPointList ($team.Group | ForEach-Object Goal)
    }
}
Save-OfficePowerPoint -Document $deck -Path .\Planning\Team-Goals.pptx
Close-OfficePowerPoint -Document $deck

Open-OfficePowerPoint -Path .\Reports\Q3-Review.pptx {
    PowerPointSlide -Title 'Appendix' {
        PowerPointList 'Data as of 30 September', 'Source: finance warehouse'
    }
}

Get-ChildItem -Path .\Decks -Filter *.pptx | ForEach-Object {
    Open-OfficePowerPoint -LiteralPath $_.FullName {
        Update-OfficePowerPointText -OldValue 'FY2025' -NewValue 'FY2026' -IncludeNotes
    }
}

$deck = Open-OfficePowerPoint -Path .\Reports\Q3-Review.pptx
try {
    Get-OfficePowerPointSlide -Document $deck -Summary | Where-Object { -not $_.HasNotes } | Select-Object SlideIndex, Title
} finally {
    Close-OfficePowerPoint -Document $deck
}

PowerPointSlide -Title 'Agenda' {
    PowerPointList 'Results', 'Risks', 'Decisions', 'Next steps'
}

$incidents = Import-OfficeExcel -Path .\Reports\Ops-October.xlsx -Sheet 'Incidents'
New-OfficePowerPoint -Path .\Reports\Service-Review-October.pptx -Theme Modern {
    PowerPointSlide -Title 'Service review' -Subtitle 'October 2026' -Eyebrow 'IT operations'
    PowerPointSlide -Title 'Health'
    PowerPointSlide -Title 'Service health' {
        PowerPointKpi '99.95%' 'Availability' -Change '+0.02 pt'
        PowerPointKpi '182 ms' 'Median latency' -Change '-14 ms'
        PowerPointKpi '7' 'Priority incidents' -Change '+2' -Color Warning
    }
    PowerPointSlide -Title 'Incidents by service' {
        PowerPointChart -InputObject $incidents -Category Service -Value Count -Type Bar
        PowerPointTable -InputObject $incidents -Property Service, Count, MeanTimeToRestore
    }
    PowerPointSlide -Title 'Change process' {
        PowerPointStep 'Request' 'Raised in the service desk'
        PowerPointStep 'Review' 'CAB approves risk and window'
        PowerPointStep 'Deploy' 'Automated with rollback'
        PowerPointStep 'Verify' 'Health checks close the change'
    }
}

New-OfficePowerPoint -Path .\Reports\All-Hands.pptx -Theme Dark {
    PowerPointSlide -Title 'All-hands' -Subtitle 'Engineering, Q4'
    PowerPointSlide -Layout Quote -Transition Fade {
        PowerPointParagraph 'Reliability is a feature our customers notice only when it is missing.'
    }
    PowerPointSlide -Title 'Thank you' -Subtitle 'Questions: #eng-all-hands' -Layout Closing
}

PowerPointParagraph {
    PowerPointText 'Overall status: '
    PowerPointText 'On track' -Bold -Color Success
}

$services = Import-OfficeExcel -Path .\Reports\Ops-October.xlsx -Sheet 'Status'
New-OfficePowerPoint -Path .\Reports\Status-Weekly.pptx {
    PowerPointSlide -Title 'Weekly status' -Subtitle 'Customer-facing services'
    PowerPointSlide -Title 'Service status' {
        PowerPointList {
            foreach ($service in $services) {
                $color = if ($service.State -eq 'Healthy') { 'Success' } else { 'Warning' }
                PowerPointListItem {
                    PowerPointText "$($service.Name): " -Bold
                    PowerPointText $service.State -Color $color
                }
            }
        }
        PowerPointParagraph {
            PowerPointText 'Live view: '
            PowerPointText 'status.contoso.com' -Link 'https://status.contoso.com'
        }
    }
}

PowerPointSlide -Title 'Why now' {
    PowerPointParagraph 'Support for the legacy CRM ends in March 2027.' -Size 24pt -Alignment Center
}

New-OfficePowerPoint -Path .\Reports\CRM-Decision.pptx {
    PowerPointSlide -Title 'CRM replacement' -Subtitle 'Decision paper'
    PowerPointSlide -Title 'Recommendation' {
        PowerPointParagraph 'Move to the hosted CRM in two waves, sales first and service second.'
        PowerPointParagraph 'The hosted option removes three on-premises servers and the yearly upgrade project.'
        PowerPointParagraph {
            PowerPointText 'Decision needed by: '
            PowerPointText '15 November' -Bold
        }
    }
}

$risks = Import-OfficeExcel -Path .\Projects\Northwind-Risks.xlsx | Where-Object Status -eq 'Open'
New-OfficePowerPoint -Path .\Projects\Northwind-Steering.pptx {
    PowerPointSlide -Title 'Northwind steering committee' -Subtitle 'Week 43'
    PowerPointSlide -Title 'Open risks' {
        PowerPointList ($risks | ForEach-Object Title)
    }
    PowerPointSlide -Title 'Cut-over sequence' {
        PowerPointList 'Freeze changes', 'Final sync', 'Switch DNS', 'Smoke test' -Numbered
    }
}

PowerPointList {
    PowerPointListItem 'Collect health signals'
    PowerPointListItem 'Review with service owners'
    PowerPointListItem 'Publish decisions'
}

$workstreams = Import-OfficeExcel -Path .\Projects\Northwind-Plan.xlsx -Sheet 'Workstreams'
New-OfficePowerPoint -Path .\Projects\Northwind-Plan.pptx {
    PowerPointSlide -Title 'Northwind plan' -Subtitle 'Workstreams and owners'
    PowerPointSlide -Title 'Workstreams' {
        PowerPointList {
            foreach ($workstream in $workstreams) {
                PowerPointListItem $workstream.Name
                PowerPointListItem -Level 2 {
                    PowerPointText 'Owner: '
                    PowerPointText $workstream.Owner -Bold
                }
            }
        }
    }
}

PowerPointSlide -Title 'Server inventory' {
    PowerPointTable -InputObject $servers
}

$patches = Import-Csv -Path .\Data\Patch-Compliance.csv
New-OfficePowerPoint -Path .\Reports\Patch-Compliance.pptx {
    PowerPointSlide -Title 'Patch compliance' -Subtitle 'October maintenance window'
    PowerPointSlide -Title 'Servers missing updates' {
        PowerPointTable -InputObject ($patches | Where-Object Missing -gt 0) -Property Server, Role, Missing, LastPatched
        PowerPointNotes 'Domain controllers are patched first in the next window.'
    }
}

PowerPointSlide -Title 'Revenue by region' {
    PowerPointChart -InputObject $sales -Category Region -Value Revenue
}

$months = Import-OfficeExcel -Path .\Reports\FY2026-Monthly.xlsx -Sheet 'Summary'
New-OfficePowerPoint -Path .\Reports\FY2026-Monthly.pptx -Theme Boardroom {
    PowerPointSlide -Title 'FY2026 monthly results' -Subtitle 'Finance update'
    PowerPointSlide -Title 'Revenue, cost and margin' {
        PowerPointChart -InputObject $months -Category Month -Value Revenue, Cost -Type Column -Title 'USD k'
        PowerPointChart -InputObject $months -Category Month -Value Margin -Type Line -Title 'Margin (%)'
        PowerPointNotes 'Cost rose in March because of the data-center move.'
    }
}

PowerPointSlide -Title 'Pipeline by stage' {
    PowerPointChart -Type Pie -Title 'Draft: data pending'
}

PowerPointSlide -Title 'Network topology' {
    PowerPointImage .\Diagrams\Topology.png -AlternativeText 'Two data centers linked to three branch offices'
}

New-OfficePowerPoint -Path .\Projects\Target-Architecture.pptx {
    PowerPointSlide -Title 'Target architecture' -Subtitle 'Northwind migration'
    PowerPointSlide -Title 'Hub and spoke network' {
        PowerPointImage .\Diagrams\Hub-Spoke.png -AlternativeText 'Hub network with three spoke networks for production, test and shared services'
        PowerPointList 'One firewall in the hub', 'Private endpoints for data services', 'No public IPs in spokes'
    }
}

$visual = ConvertTo-OfficeVisual -InputObject .\Charts\Latency-P95.svg -Title 'P95 latency'
PowerPointSlide -Title 'Latency trend' {
    PowerPointImage -InputObject $visual -AlternativeText 'P95 latency fell from 240 ms to 180 ms over six weeks'
}

PowerPointSlide -Title 'Budget' {
    PowerPointChart -InputObject $budget -Category Department -Value Spend
    PowerPointNotes 'Pause here for questions about the budget.'
}

$regions = Import-OfficeExcel -Path .\Reports\Q3-Sales.xlsx -Sheet 'By region'
New-OfficePowerPoint -Path .\Reports\Q3-Regions.pptx {
    PowerPointSlide -Title 'Q3 regional results'
    foreach ($region in $regions) {
        PowerPointSlide -Title $region.Region {
            PowerPointKpi $region.Revenue 'Revenue'
            PowerPointKpi $region.Deals 'Deals closed'
            PowerPointNotes $region.TalkingPoint
        }
    }
}

PowerPointSlide -Title 'Service health' {
    PowerPointKpi '99.95%' 'Availability'
    PowerPointKpi '182 ms' 'Median latency'
}

$tickets = Import-Csv -Path .\Data\Tickets-October.csv
$closed = @($tickets | Where-Object Status -eq 'Closed')
$breached = @($tickets | Where-Object SlaBreached -eq 'True')
New-OfficePowerPoint -Path .\Reports\Support-October.pptx {
    PowerPointSlide -Title 'Support review' -Subtitle 'October 2026'
    PowerPointSlide -Title 'October at a glance' {
        PowerPointKpi $tickets.Count 'Tickets opened' -Change '+6% vs September' -Trend Up -GoodDirection Down
        PowerPointKpi $closed.Count 'Tickets closed' -Change '+11%' -Trend Up
        PowerPointKpi '4.6 / 5' 'Satisfaction' -Change '+0.1' -Trend Up
        PowerPointKpi $breached.Count 'SLA breaches' -Change '+3' -Trend Up -GoodDirection Down
    }
}

PowerPointSlide -Title 'This week' {
    PowerPointKpi '99.95%' 'Availability' -Delta 0.02 -DeltaUnit pt
    PowerPointKpi '182 ms' 'Median response' -Delta -14 -DeltaUnit ms -GoodDirection Down
}

PowerPointSlide -Title 'Current signals' {
    PowerPointCard 'Availability' -Text 'All regions healthy'
    PowerPointCard 'Capacity' -Text 'Storage at 71%'
    PowerPointCard 'Risk' -Text 'One vendor dependency on watch'
}

New-OfficePowerPoint -Path .\Sales\Managed-Services.pptx -Theme Modern {
    PowerPointSlide -Title 'Managed services' -Subtitle 'What we run for you'
    PowerPointSlide -Title 'Capabilities' {
        PowerPointCard 'Identity' -Text 'Directory and access management' -Items 'Single sign-on', 'MFA', 'Access reviews'
        PowerPointCard 'Endpoints' -Text 'Devices that stay compliant' -Items 'Windows and macOS', 'Patching', 'Encryption'
        PowerPointCard 'Monitoring' -Text 'Around-the-clock operations' -Items '24x7 desk', 'Alerting', 'Monthly reports'
    }
}

PowerPointSlide -Title 'Systems covered' {
    PowerPointCard 'Directory' -Image .\Logos\Directory.png
    PowerPointCard 'Mail' -Image .\Logos\Mail.png
    PowerPointCard 'Backup' -Image .\Logos\Backup.png
    PowerPointCard 'Monitoring' -Image .\Logos\Monitoring.png
}

PowerPointSlide -Title 'Operating rhythm' {
    PowerPointStep 'Collect' 'Gather health signals'
    PowerPointStep 'Review' 'Confirm decisions with owners'
    PowerPointStep 'Act' 'Track actions to closure'
}

New-OfficePowerPoint -Path .\Projects\Mail-Migration.pptx {
    PowerPointSlide -Title 'Mail migration' -Subtitle 'Plan for November'
    PowerPointSlide -Title 'Five-week plan' {
        PowerPointStep 'Pilot' 'IT and two volunteer teams' -Number 'Week 1'
        PowerPointStep 'Wave 1' 'Head office, 400 mailboxes' -Number 'Week 2'
        PowerPointStep 'Wave 2' 'Regional offices, 650 mailboxes' -Number 'Week 3'
        PowerPointStep 'Shared mailboxes' 'Rooms and team mailboxes' -Number 'Week 4'
        PowerPointStep 'Decommission' 'Retire the old mail servers' -Number 'Week 5'
    }
}

PowerPointSlide -Title 'Regional coverage' {
    PowerPointLocation 'Dublin' -MapLeft 0.45 -MapTop 0.3 -Detail 'Primary operations'
}

$sites = Import-OfficeExcel -Path .\Inventory\Sites.xlsx -Sheet 'Data centers'
New-OfficePowerPoint -Path .\Inventory\Coverage.pptx {
    PowerPointSlide -Title 'Where we run' -Subtitle 'Data centers and roles'
    PowerPointSlide -Title 'Data centers' {
        foreach ($site in $sites) {
            PowerPointLocation $site.City -MapLeft $site.MapLeft -MapTop $site.MapTop -Detail $site.Role
        }
    }
}

PowerPointSlide {
    PowerPointQuote 'The new intake form cut our wait time in half.' 'Anna Nowak, East depot'
}

$comments = Import-OfficeExcel -Path .\Survey\Results.xlsx -Sheet 'Comments'
$best = $comments | Sort-Object -Property Rating -Descending | Select-Object -First 1
New-OfficePowerPoint -Path .\Survey\Review.pptx -Author 'Service desk' -Date (Get-Date) {
    PowerPointSlide -Title 'Service desk survey' -Subtitle 'October 2026'
    PowerPointSlide {
        PowerPointQuote $best.Comment "$($best.Name), $($best.Site)"
    }
    PowerPointSlide -Title 'Thank you'
}

PowerPointSlide -Title 'Build or buy' {
    PowerPointColumn -Title 'Build' {
        PowerPointList 'Full control', 'Six months to first release'
    }
    PowerPointColumn -Title 'Buy' {
        PowerPointList 'Live in six weeks', 'Yearly subscription'
    }
}

$before = Import-OfficeExcel -Path .\Projects\Northwind-Costs.xlsx -Sheet 'On-premises'
$after = Import-OfficeExcel -Path .\Projects\Northwind-Costs.xlsx -Sheet 'Hosted'
New-OfficePowerPoint -Path .\Projects\Northwind-Costs.pptx {
    PowerPointSlide -Title 'Running costs' -Subtitle 'Before and after the migration'
    PowerPointSlide -Title 'Yearly cost by item' {
        PowerPointColumn -Title 'On-premises' {
            PowerPointChart -InputObject $before -Category Item -Value Cost -Type Pie
            PowerPointParagraph 'USD 412k per year'
        }
        PowerPointColumn -Title 'Hosted' {
            PowerPointChart -InputObject $after -Category Item -Value Cost -Type Pie
            PowerPointParagraph 'USD 268k per year'
        }
    }
}

New-OfficePowerPoint -Path .\Reports\Q3-Review.pptx {
    PowerPointFooter 'Contoso | Internal'
    PowerPointSlide -Title 'Q3 business review'
}

New-OfficePowerPoint -Path .\Reports\Security-Review.pptx -Theme Boardroom {
    PowerPointFooter 'Contoso | Confidential' -Alignment Left
    PowerPointFooter -Alignment Right {
        PowerPointSlideNumber
    }
    PowerPointSlide -Title 'Security review' -Subtitle 'Q3 2026'
    PowerPointSlide -Title 'External audit findings' {
        PowerPointTable -InputObject $findings -Property Finding, Severity, Owner
        PowerPointFooter 'Source: external audit report, September 2026'
    }
}

PowerPointFooter {
    PowerPointSlideNumber
}

New-OfficePowerPoint -Path .\Reports\Board-Pack.pptx -Theme Boardroom {
    PowerPointFooter {
        PowerPointText 'Board pack, November 2026 | Slide '
        PowerPointSlideNumber
    }
    PowerPointSlide -Title 'Board pack' -Subtitle 'November 2026'
    PowerPointSlide -Title 'Agenda' {
        PowerPointList 'Financial results', 'Risk register', 'Approvals'
    }
}

$trend = Import-OfficeExcel -Path .\Reports\FY2026-Monthly.xlsx -Sheet 'Summary'
New-OfficePowerPoint -Path .\Reports\Revenue-Trend.pptx {
    PowerPointSlide -Title 'Revenue trend' {
        PowerPointChart -InputObject $trend -Category Month -Value Revenue -Type Line
        PowerPointTextBox -Name 'Callout' -X 18cm -Y 5cm -Width 8cm -Height 2.5cm {
            PowerPointParagraph {
                PowerPointText 'Record month: ' -Bold
                PowerPointText 'March, after the spring campaign'
            }
        }
    }
}

$services = Import-OfficeExcel -Path .\Reports\Ops-October.xlsx -Sheet 'Status'
New-OfficePowerPoint -Path .\Reports\Status-Board.pptx {
    PowerPointSlide -Title 'Service status board' {
        $lights = foreach ($service in $services) {
            $color = switch ($service.State) { 'Healthy' { 'Success' } 'Degraded' { 'Warning' } default { 'Danger' } }
            PowerPointShape -Type Ellipse -Name "Status-$($service.Name)" -FillColor $color -X 2cm -Y 8cm -Width 2cm -Height 2cm -PassThru
        }
        $lights | PowerPointShapeLayout -Distribute Horizontal -ToSlide -Margin 2cm
    }
}

New-OfficePowerPoint -Path .\Reports\Q3-Partner-Update.pptx -Theme .\Templates\Contoso-2026.potx {
    PowerPointSlide -TemplateLayout 'Title Slide' {
        PowerPointPlaceholder -Type CenteredTitle 'Partner update'
        PowerPointPlaceholder -Type SubTitle 'Q3 2026'
    }
    PowerPointSlide -TemplateLayout 'Title and Content' {
        PowerPointPlaceholder -Type Title 'Highlights'
        PowerPointPlaceholder -Type Body {
            PowerPointParagraph 'Three new regions live'
            PowerPointParagraph 'Partner portal adoption at 74%'
        }
        PowerPointPlaceholder -Type Footer 'Partner confidential' -IgnoreMissing
    }
}

Open-OfficePowerPoint -Path .\Reports\Q3-Review.pptx {
    PowerPointSection 'Appendix' -Slide 9
}

Open-OfficePowerPoint -Path .\Signage\Lobby-Welcome.pptx {
    Set-OfficePowerPointSlideSize Screen16x9 -Portrait
}

New-OfficePowerPoint -Path .\Reports\Engineering-Update.pptx {
    PowerPointSlide -Title 'Engineering update' -Subtitle 'Week 43'
    Get-ChildItem -Path .\Updates -Filter *.pptx | Sort-Object Name | ForEach-Object {
        Import-OfficePowerPointSlide -LiteralPath $_.FullName -SourceSlide 1, 2
    }
}

New-OfficePowerPoint -Path .\Reports\Customer-Proposal.pptx {
    PowerPointSlide -Title 'Managed services proposal' -Subtitle 'Northwind Traders'
    Import-OfficePowerPointSlide -Path .\Library\Standard-Appendix.pptx
}

Get-ChildItem -Path .\Decks -Filter *.pptx | ForEach-Object {
    $deck = Open-OfficePowerPoint -LiteralPath $_.FullName
    Rename-OfficePowerPointSection -Document $deck -Name 'Next steps' -NewName 'Decisions'
    Save-OfficePowerPoint -Document $deck
    Close-OfficePowerPoint -Document $deck
}

Open-OfficePowerPoint -Path .\Reports\Q3-Review.pptx {
    Rename-OfficePowerPointSection -Name 'Backup' -NewName 'Appendix'
}

$deck = Open-OfficePowerPoint -Path .\Reports\Q3-Review.pptx
$notes = Get-OfficePowerPointNotes -Document $deck -IncludeEmpty
Close-OfficePowerPoint -Document $deck
New-OfficeWord -Path .\Reports\Q3-Review-Script.docx {
    WordHeading 'Q3 review: presenter script'
    foreach ($note in $notes) {
        WordHeading "Slide $($note.SlideIndex)" -Level 2
        WordParagraph $note.Text
    }
}

$deck = Open-OfficePowerPoint -Path .\Reports\Revenue-Trend.pptx
$callout = Get-OfficePowerPointShape -Document $deck -Name 'Callout'
Set-OfficePowerPointShapeText -InputObject $callout -Content {
    PowerPointParagraph {
        PowerPointText 'Risk: ' -Bold
        PowerPointText 'Q4 pipeline 18% below plan' -Color Danger
    }
}
Save-OfficePowerPoint -Document $deck
Close-OfficePowerPoint -Document $deck

$deck = Open-OfficePowerPoint -Path .\Projects\Northwind-Plan.pptx
$milestones = Get-OfficePowerPointShape -Document $deck -Text 'Milestone' -Kind Table | Select-Object -First 1
Set-OfficePowerPointTableCell -InputObject $milestones -Row 4 -Column 3 -Content {
    PowerPointParagraph {
        PowerPointText 'Late: ' -Bold -Color Danger
        PowerPointText 'moved to 28 November'
    }
}
Save-OfficePowerPoint -Document $deck
Close-OfficePowerPoint -Document $deck

$values = @{
    '{{Customer}}' = 'Northwind Traders'
    '{{Quarter}}'  = 'Q3 2026'
    '{{Manager}}'  = 'Alex Johnson'
}
Open-OfficePowerPoint -Path .\Templates\Account-Review.pptx {
    foreach ($token in $values.Keys) {
        $count = Update-OfficePowerPointText -OldValue $token -NewValue $values[$token] -IncludeNotes -PassThru
        Write-Verbose "$token replaced $count times"
    }
}

Get-ChildItem -Path .\Decks -Filter *.pptx | ForEach-Object {
    $deck = Open-OfficePowerPoint -LiteralPath $_.FullName
    $theme = Get-OfficePowerPointTheme -Document $deck
    Close-OfficePowerPoint -Document $deck
    if ($theme.ThemeName -ne 'Contoso 2026') {
        [pscustomobject]@{ Deck = $_.Name; Theme = $theme.ThemeName }
    }
}

Get-ChildItem -Path .\Decks -Filter *.pptx | ForEach-Object {
    Open-OfficePowerPoint -LiteralPath $_.FullName {
        Set-OfficePowerPointTheme -Theme .\Templates\Contoso-2026.potx -AllMasters
    }
}

Open-OfficePowerPoint -Path .\Sales\Managed-Services.pptx {
    Set-OfficePowerPointTheme -Colors @{ Accent1 = '#0F766E'; Accent2 = '#F59E0B' } -HeadingFont 'Segoe UI Semibold' -BodyFont 'Segoe UI' -Name 'Contoso Services'
}

$deck = New-OfficePowerPoint -Path .\Reports\Pillars.pptx
$columns = Get-OfficePowerPointLayoutBox -Document $deck -Columns 3 -Margin 1.5cm -Gutter 1cm
$pillars = 'Secure', 'Reliable', 'Affordable'
PowerPointSlide -Document $deck -Title 'Our pillars' {
    for ($i = 0; $i -lt $columns.Count; $i++) {
        $box = $columns[$i]
        PowerPointShape -Type RoundRectangle -Name $pillars[$i] -X $box.X -Y $box.Y -Width $box.Width -Height $box.Height
        PowerPointTextBox $pillars[$i] -X $box.X -Y $box.Y -Width $box.Width -Height 2cm
    }
}
Save-OfficePowerPoint -Document $deck
Close-OfficePowerPoint -Document $deck

Get-ChildItem -Path .\Publish -Filter *.pptx | ForEach-Object {
    $report = Test-OfficePowerPoint -LiteralPath $_.FullName -Options (New-OfficePowerPointInspectionOptions -Visuals)
    if ($report.PackageErrors.Count -gt 0) {
        [pscustomobject]@{ Deck = $_.Name; Errors = $report.PackageErrors.Count }
    }
}

$full = New-OfficePowerPointInspectionOptions -Features -ReviewComments -Animations -Signatures -Visuals
Get-ChildItem -Path .\Release -Filter *.pptx |
    ForEach-Object { Test-OfficePowerPoint -LiteralPath $_.FullName -Options $full }
